import type { ЯзыкиРегиона } from "../core";

/** Названия и описания мест на zh, ko, de, fr, ja, tr, ar. */
export const ЯЗЫКИ_ХОРЕЗМА: ЯзыкиРегиона = {
  "kh-ichankala": {
    zh: { name: "伊钦卡拉", desc: "希瓦的内城：一座位于厚重土坯城墙后的露天博物馆，也是中亚第一个列入联合国教科文组织名录的遗产（1990年）。在约26公顷的范围内有五十多处古迹——经学院、清真寺、宣礼塔、汗王宫殿和陵墓——其间是至今仍有人居住的普通民居。大多数建筑凭一张通票即可参观，通票在西门奥塔大门出售。最佳时间是清晨和日落，那时城墙和宣礼塔泛着金光，夜晚小巷灯火通明。" },
    ko: { name: "이찬 칼라", desc: "히바의 내성으로, 거대한 흙벽돌 성벽 안의 야외 박물관이자 중앙아시아 최초의 유네스코 세계유산(1990)입니다. 약 26헥타르 안에 마드라사, 모스크, 미나레트, 칸의 궁전, 영묘 등 50곳이 넘는 유적이 있고, 그 사이에 지금도 사람들이 사는 평범한 집들이 있습니다. 대부분의 건물은 서문 오타 다르보자에서 파는 통합권 한 장으로 들어갈 수 있습니다. 성벽과 미나레트가 금빛으로 빛나는 이른 아침과 해 질 녘이 가장 좋고, 밤에는 골목에 불이 켜집니다." },
    de: { name: "Itschan Kala", desc: "Die Innenstadt von Chiwa: ein Freilichtmuseum hinter mächtigen Lehmziegelmauern und die erste Stätte Zentralasiens auf der UNESCO-Liste (1990). Auf rund 26 Hektar stehen mehr als fünfzig Denkmäler – Medresen, Moscheen, Minarette, Khanspaläste und Mausoleen –, dazwischen gewöhnliche Häuser, in denen noch Menschen wohnen. Die meisten Gebäude sind mit einem einzigen Ticket zugänglich, das am westlichen Tor Ota Darvoza verkauft wird. Am schönsten ist es frühmorgens und bei Sonnenuntergang, wenn Mauern und Minarette golden leuchten; nachts sind die Gassen beleuchtet." },
    fr: { name: "Itchan Kala", desc: "La ville intérieure de Khiva : un musée à ciel ouvert derrière de massives murailles de brique crue et le premier site d'Asie centrale inscrit sur la liste de l'UNESCO (1990). Sur environ 26 hectares se dressent plus de cinquante monuments – médersas, mosquées, minarets, palais des khans et mausolées – avec, entre eux, des maisons ordinaires toujours habitées. La plupart des édifices se visitent avec un billet unique vendu à la porte ouest Ota Darvoza. Les meilleurs moments sont tôt le matin et au coucher du soleil, quand murailles et minarets s'embrasent d'or ; la nuit, les ruelles sont illuminées." },
    ja: { name: "イチャン・カラ", desc: "ヒヴァの内城で、巨大な日干しレンガの城壁に囲まれた屋外博物館であり、中央アジアで初めてユネスコ世界遺産に登録された場所です（1990年）。約26ヘクタールの中に、メドレセ、モスク、ミナレット、ハンの宮殿、霊廟など50を超える建造物が立ち、その間には今も人が暮らす普通の家々があります。ほとんどの建物は、西門オタ・ダルヴォザで売られる共通券1枚で見学できます。城壁とミナレットが金色に輝く早朝と夕暮れが最高で、夜は路地がライトアップされます。" },
    tr: { name: "İçan Kale", desc: "Hive'nin iç şehri: masif kerpiç surların ardında bir açık hava müzesi ve UNESCO listesine giren ilk Orta Asya alanı (1990). Yaklaşık 26 hektarlık alanda elliden fazla anıt – medreseler, camiler, minareler, han sarayları ve türbeler – ve aralarında insanların hâlâ yaşadığı sıradan evler bulunur. Yapıların çoğu batıdaki Ata Kapı'da satılan tek bir biletle gezilir. En güzel zamanlar, surların ve minarelerin altın gibi parladığı sabah erken saatler ve gün batımıdır; geceleri sokaklar ışıklandırılır." },
    ar: { name: "إيتشان قلعة", desc: "المدينة الداخلية في خيوة: متحف مفتوح خلف أسوار ضخمة من الطوب اللبن، وأول موقع في آسيا الوسطى يُدرج في قائمة اليونسكو (1990). على مساحة نحو 26 هكتارًا يقوم أكثر من خمسين معلمًا – مدارس ومساجد ومآذن وقصور الخانات وأضرحة – وبينها بيوت عادية لا يزال الناس يسكنونها. تُزار معظم المباني بتذكرة واحدة تُباع عند البوابة الغربية «أتا دروازه». أفضل الأوقات الصباح الباكر والغروب، حين تتوهج الأسوار والمآذن ذهبًا، وتُضاء الأزقة ليلًا." },
  },
  "kh-walls": {
    zh: { name: "伊钦卡拉城墙与城门", desc: "高达10米、布满圆塔的厚重土坯城墙环绕希瓦内城两公里多。四座城门朝向四方：西面的奥塔大门是正门，北面是博格恰大门，东面是带长长的有顶商铺廊道的帕尔万大门，南面是托什大门。部分城墙开放供人在墙顶漫步，可以看到映衬在沙漠背景下的穹顶和宣礼塔。北门在日落时分尤其美丽。" },
    ko: { name: "이찬 칼라 성벽과 성문", desc: "높이 최대 10m, 둥근 탑이 촘촘히 박힌 거대한 흙벽돌 성벽이 2km 넘게 히바 내성을 둘러싸고 있습니다. 네 개의 성문이 동서남북을 향하는데, 서쪽 오타 다르보자가 정문이고, 북쪽 보그차 다르보자, 긴 지붕 덮인 상점 회랑이 있는 동쪽 팔본 다르보자, 남쪽 토시 다르보자가 있습니다. 성벽 일부는 위를 걸을 수 있게 개방되어 사막을 배경으로 한 돔과 미나레트가 보입니다. 북문은 해 질 녘에 특히 아름답습니다." },
    de: { name: "Mauern und Tore von Itschan Kala", desc: "Mächtige Lehmziegelmauern von bis zu 10 Metern Höhe, besetzt mit runden Türmen, umschließen Chiwas Innenstadt auf mehr als zwei Kilometern. Vier Tore weisen in die Himmelsrichtungen: das westliche Ota Darvoza ist der Haupteingang, dazu das nördliche Bogcha Darvoza, das östliche Palvan Darvoza mit seiner langen überdachten Ladengalerie und das südliche Tosh Darvoza. Ein Teil der Mauern ist für einen Spaziergang oben offen, mit Blick auf Kuppeln und Minarette vor der Wüste. Das Nordtor ist bei Sonnenuntergang besonders schön." },
    fr: { name: "Murailles et portes d'Itchan Kala", desc: "De massives murailles de brique crue hautes jusqu'à 10 mètres, hérissées de tours rondes, ceinturent la ville intérieure de Khiva sur plus de deux kilomètres. Quatre portes regardent les points cardinaux : à l'ouest Ota Darvoza, l'entrée principale, au nord Bogtcha Darvoza, à l'est Palvan Darvoza avec sa longue galerie couverte de boutiques, et au sud Toch Darvoza. Une partie des murailles est ouverte à la promenade sur le chemin de ronde, avec vue sur les coupoles et minarets sur fond de désert. La porte nord est particulièrement belle au coucher du soleil." },
    ja: { name: "イチャン・カラの城壁と門", desc: "高さ最大10m、円塔をちりばめた巨大な日干しレンガの城壁が、2km以上にわたってヒヴァの内城を取り囲んでいます。4つの門が東西南北を向き、西のオタ・ダルヴォザが正門、北のボグチャ・ダルヴォザ、屋根付きの長い商店回廊を持つ東のパルヴァン・ダルヴォザ、南のトシュ・ダルヴォザがあります。城壁の一部は上を歩けるよう開放されており、砂漠を背景にしたドームとミナレットが見渡せます。北門は夕暮れ時が特に美しいです。" },
    tr: { name: "İçan Kale Surları ve Kapıları", desc: "10 metreye varan yükseklikte, yuvarlak kulelerle donatılmış masif kerpiç surlar, Hive'nin iç şehrini iki kilometreden uzun bir hat boyunca çevreler. Dört kapı dört yöne bakar: batıdaki Ata Kapı ana giriştir; kuzeyde Bahçe Kapı, doğuda uzun kapalı dükkân galerisiyle Pehlivan Kapı ve güneyde Taş Kapı vardır. Surların bir bölümü üstünde yürümeye açıktır; çöl önünde kubbeler ve minareler görülür. Kuzey kapısı gün batımında özellikle güzeldir." },
    ar: { name: "أسوار وبوابات إيتشان قلعة", desc: "أسوار ضخمة من الطوب اللبن يصل ارتفاعها إلى 10 أمتار، مرصعة بأبراج مستديرة، تطوّق المدينة الداخلية في خيوة على امتداد أكثر من كيلومترين. أربع بوابات تتجه إلى الجهات الأصلية: الغربية «أتا دروازه» هي المدخل الرئيسي، والشمالية «باغتشه دروازه»، والشرقية «بهلوان دروازه» برواقها الطويل المسقوف للمتاجر، والجنوبية «طاش دروازه». جزء من الأسوار مفتوح للمشي فوقها، مع إطلالة على القباب والمآذن أمام الصحراء. والبوابة الشمالية جميلة بشكل خاص عند الغروب." },
  },
  "kh-kunyaark": {
    zh: { name: "库尼亚·阿尔克城堡", desc: "“老城堡”，希瓦汗王的宫邸，位于伊钦卡拉西门旁，是一座有自己城墙的城中之城。它始建于17世纪末；内部保存着带瓷砖伊万的库里尼什哈纳觐见庭院、1838年饰有蓝白马约利卡彩陶的夏季清真寺、汗国造币厂和后宫。最精彩的是登上阿克谢赫·博博堡垒，这里能看到伊钦卡拉最好的景色，尤其是日落时。登堡垒单独收费。" },
    ko: { name: "쿠냐 아르크 성채", desc: "‘옛 요새’라는 뜻으로, 이찬 칼라 서문 옆에 있는 히바 칸들의 거처이며, 자체 성벽을 갖춘 도시 속의 도시입니다. 17세기 말에 지어졌으며, 안에는 타일 이완이 있는 쿠리니시하나 알현 정원, 청백색 마졸리카로 장식한 1838년의 여름 모스크, 칸국의 조폐소와 하렘이 남아 있습니다. 하이라이트는 아크 셰이흐 보보 보루에 오르는 것으로, 특히 해 질 녘 이찬 칼라의 가장 좋은 전망을 볼 수 있습니다. 보루 오르기는 별도 요금입니다." },
    de: { name: "Zitadelle Kunja Ark", desc: "Die „Alte Festung“, Residenz der Khane von Chiwa am Westtor von Itschan Kala, eine Stadt in der Stadt mit eigener Mauer. Sie stammt vom Ende des 17. Jahrhunderts; erhalten sind der Thronhof Kurinischchana mit gefliestem Iwan, die Sommermoschee von 1838 mit blau-weißer Majolika, die Münzstätte der Khane und der Harem. Höhepunkt ist der Aufstieg auf die Bastion Ak Scheich Bobo, die den besten Blick über Itschan Kala bietet, besonders bei Sonnenuntergang. Der Aufstieg kostet extra." },
    fr: { name: "Citadelle de Kounia Ark", desc: "La « vieille forteresse », résidence des khans de Khiva près de la porte ouest d'Itchan Kala, ville dans la ville avec sa propre enceinte. Elle date de la fin du XVIIe siècle ; à l'intérieur subsistent la cour du trône kourinichkhana avec son iwan carrelé, la mosquée d'été de 1838 à la majolique bleue et blanche, l'hôtel des monnaies des khans et le harem. Le clou de la visite est la montée au bastion d'Ak Cheikh Bobo, qui offre la plus belle vue sur Itchan Kala, surtout au coucher du soleil. La montée se paie à part." },
    ja: { name: "クフナ・アルク城塞", desc: "「古い要塞」を意味し、イチャン・カラ西門のそばにあるヒヴァのハンたちの居城で、独自の城壁を持つ町の中の町です。17世紀末に築かれ、内部にはタイル張りのイーワーンを持つ謁見の中庭クリニシュハナ、青と白のマヨリカ焼で飾られた1838年の夏のモスク、ハンの造幣所、ハレムが残っています。ハイライトはアク・シェイフ・ボボの稜堡に登ることで、特に夕暮れ時にイチャン・カラを最もよく見渡せます。登るのは別料金です。" },
    tr: { name: "Köhne Erk Kalesi", desc: "“Eski Kale”; İçan Kale'nin batı kapısının yanında Hive hanlarının ikametgâhı, kendi suru olan şehir içinde bir şehir. 17. yüzyıl sonundan kalmadır; içinde çinili eyvanıyla küriniş-hane taht avlusu, mavi-beyaz majolikalı 1838 tarihli yazlık cami, hanların darphanesi ve harem korunmuştur. En güzel kısmı, özellikle gün batımında İçan Kale'nin en iyi manzarasını sunan Ak Şeyh Baba burcuna çıkmaktır. Çıkış ayrıca ücretlidir." },
    ar: { name: "قلعة كونيا أرك", desc: "«القلعة القديمة»، مقر خانات خيوة عند البوابة الغربية لإيتشان قلعة، مدينة داخل المدينة بسورها الخاص. تعود إلى أواخر القرن السابع عشر؛ وفي داخلها باحة العرش «كورينيش خانه» بإيوانها المكسو بالبلاط، والمسجد الصيفي لعام 1838 بخزفه الأزرق والأبيض، ودار سك العملة للخانات، والحريم. وأبرز ما فيها الصعود إلى برج «آق شيخ بابا» الذي يمنح أفضل إطلالة على إيتشان قلعة، خاصة عند الغروب. الصعود مدفوع على حدة." },
  },
  "kh-kaltaminor": {
    zh: { name: "卡尔塔·米诺尔宣礼塔", desc: "希瓦最具辨识度的象征：粗壮的“短宣礼塔”，全身覆盖着绿松石色、蓝色和白色的釉面砖。穆罕默德·阿明汗在1850年代开始修建，想让它成为伊斯兰世界最高的宣礼塔，在塔顶能望见布哈拉。但汗王于1855年在征战中被杀，工程停在约29米处。这座未完成的塔立在西门几步之遥的穆罕默德·阿明汗经学院旁；不能攀登。" },
    ko: { name: "칼타 미노르 미나레트", desc: "히바를 가장 잘 상징하는 건축물로, 청록색, 파란색, 흰색 유약 타일로 완전히 덮인 굵은 ‘짧은 미나레트’입니다. 무함마드 아민 칸이 1850년대에 꼭대기에서 부하라가 보일 만큼 이슬람 세계에서 가장 높은 미나레트를 만들려고 착공했습니다. 그러나 칸이 1855년 원정 중 전사하면서 공사는 약 29m에서 멈췄습니다. 미완성의 탑은 서문에서 몇 걸음 떨어진 무함마드 아민 칸 마드라사 옆에 서 있으며, 오를 수는 없습니다." },
    de: { name: "Minarett Kalta Minor", desc: "Chiwas bekanntestes Wahrzeichen: das breite „Kurze Minarett“, vollständig mit türkisfarbenen, blauen und weißen Glasurfliesen verkleidet. Muhammad Amin Khan begann es in den 1850er-Jahren und wollte es zum höchsten der islamischen Welt machen, damit man von oben Buchara sehen könne. Doch der Khan fiel 1855 auf einem Feldzug, und der Bau endete bei etwa 29 Metern. Der unvollendete Turm steht neben der Medrese Muhammad Amin Khan, wenige Schritte vom Westtor; besteigen kann man ihn nicht." },
    fr: { name: "Minaret Kalta Minor", desc: "Le symbole le plus reconnaissable de Khiva : le large « minaret court », entièrement revêtu de carreaux émaillés turquoise, bleus et blancs. Muhammad Amin Khan le commença dans les années 1850, voulant en faire le plus haut du monde islamique pour qu'on puisse voir Boukhara depuis son sommet. Mais le khan fut tué en campagne en 1855 et la construction s'arrêta à environ 29 mètres. La tour inachevée se dresse près de la médersa Muhammad Amin Khan, à quelques pas de la porte ouest ; on ne peut pas y monter." },
    ja: { name: "カルタ・ミノル", desc: "ヒヴァで最もよく知られたシンボルで、ターコイズ、青、白の施釉タイルで全面が覆われた太い「短いミナレット」です。ムハンマド・アミン・ハンが1850年代に、頂上からブハラが見えるほどイスラム世界で最も高いミナレットにしようと建設を始めました。しかしハンは1855年に遠征中に戦死し、工事は約29mで止まりました。未完成の塔は西門から数歩のムハンマド・アミン・ハン・メドレセの隣に立っており、登ることはできません。" },
    tr: { name: "Kalta Minar", desc: "Hive'nin en tanınmış simgesi: tamamen turkuaz, mavi ve beyaz sırlı çinilerle kaplı geniş “Kısa Minare”. Muhammed Emin Han 1850'lerde, tepesinden Buhara görülebilsin diye İslam dünyasının en yüksek minaresi olmasını amaçlayarak inşaatına başladı. Ancak han 1855'te bir seferde öldürüldü ve inşaat yaklaşık 29 metrede durdu. Yarım kalan kule, batı kapısından birkaç adım ötedeki Muhammed Emin Han Medresesi'nin yanında durur; çıkılamaz." },
    ar: { name: "مئذنة كالتا مينور", desc: "أشهر رموز خيوة: «المئذنة القصيرة» العريضة، المكسوة كلها ببلاط مزجج فيروزي وأزرق وأبيض. بدأها محمد أمين خان في خمسينيات القرن التاسع عشر قاصدًا أن تكون أعلى مئذنة في العالم الإسلامي حتى تُرى بخارى من قمتها. لكن الخان قُتل في حملة عام 1855 وتوقف البناء عند نحو 29 مترًا. ويقف البرج غير المكتمل بجوار مدرسة محمد أمين خان على بعد خطوات من البوابة الغربية؛ ولا يمكن صعوده." },
  },
  "kh-aminkhan": {
    zh: { name: "穆罕默德·阿明汗经学院", desc: "希瓦最大的经学院，由穆罕默德·阿明汗于1851–1855年建在伊钦卡拉西门旁，紧邻卡尔塔·米诺尔宣礼塔。这座有巨大门楼和角塔的两层建筑有一百多间小室，还曾是汗国的最高伊斯兰法庭所在地。立面饰有马约利卡彩陶和雕刻铭文。经学院就在城门口，因此它的门楼自然是游览伊钦卡拉的起点。" },
    ko: { name: "무함마드 아민 칸 마드라사", desc: "히바 최대의 마드라사로, 무함마드 아민 칸이 1851~1855년 이찬 칼라 서문 옆, 칼타 미노르 미나레트 바로 곁에 지었습니다. 거대한 정문과 모서리 탑을 갖춘 2층 건물에는 100개가 넘는 방이 있었고, 칸국의 최고 이슬람 법정도 이곳에 있었습니다. 정면은 마졸리카와 조각 명문으로 장식되어 있습니다. 마드라사가 도시 입구에 있어 그 정문이 이찬 칼라 산책의 자연스러운 출발점이 됩니다." },
    de: { name: "Medrese Muhammad Amin Khan", desc: "Chiwas größte Medrese, 1851–1855 von Muhammad Amin Khan am Westtor von Itschan Kala neben dem Minarett Kalta Minor erbaut. Der zweigeschossige Bau mit riesigem Portal und Ecktürmen hatte mehr als hundert Zellen und beherbergte auch das oberste islamische Gericht des Khanats. Die Fassade ist mit Majolika und geschnitzten Inschriften geschmückt. Die Medrese steht direkt am Eingang der Stadt, ihr Portal ist daher der natürliche Ausgangspunkt eines Rundgangs durch Itschan Kala." },
    fr: { name: "Médersa Muhammad Amin Khan", desc: "La plus grande médersa de Khiva, bâtie en 1851–1855 par Muhammad Amin Khan près de la porte ouest d'Itchan Kala, à côté du minaret Kalta Minor. L'édifice à deux niveaux, avec un immense portail et des tours d'angle, comptait plus de cent cellules et abritait aussi la cour islamique suprême du khanat. Sa façade est ornée de majolique et d'inscriptions sculptées. La médersa se trouve à l'entrée même de la ville ; son portail est donc le point de départ naturel d'une promenade dans Itchan Kala." },
    ja: { name: "ムハンマド・アミン・ハン・メドレセ", desc: "ヒヴァ最大のメドレセで、ムハンマド・アミン・ハンが1851～1855年にイチャン・カラ西門のそば、カルタ・ミノルの隣に建てました。巨大な門と隅塔を持つ2階建ての建物には100を超える小部屋があり、ハン国の最高イスラム法廷も置かれていました。ファサードはマヨリカ焼と彫刻の銘文で飾られています。メドレセは町の入口に立っているので、その門がイチャン・カラ散策の自然な出発点になります。" },
    tr: { name: "Muhammed Emin Han Medresesi", desc: "Hive'nin en büyük medresesi; 1851–1855'te Muhammed Emin Han tarafından İçan Kale'nin batı kapısının yanında, Kalta Minar'ın bitişiğinde yaptırıldı. Dev taç kapılı ve köşe kuleli iki katlı yapıda yüzden fazla hücre vardı ve hanlığın yüksek İslami mahkemesi de burada bulunuyordu. Cephesi majolika ve oyma yazıtlarla süslüdür. Medrese şehrin tam girişindedir, bu yüzden taç kapısı İçan Kale gezisinin doğal başlangıç noktasıdır." },
    ar: { name: "مدرسة محمد أمين خان", desc: "أكبر مدارس خيوة، بناها محمد أمين خان بين 1851 و1855 عند البوابة الغربية لإيتشان قلعة بجوار مئذنة كالتا مينور. كان المبنى ذو الطابقين ببوابته الضخمة وأبراجه الركنية يضم أكثر من مئة حجرة، وكان مقرًا للمحكمة الإسلامية العليا في الخانية. واجهته مزينة بالخزف المزجج والنقوش المنحوتة. تقف المدرسة عند مدخل المدينة مباشرة، فبوابتها نقطة البداية الطبيعية لجولة في إيتشان قلعة." },
  },
  "kh-juma": {
    zh: { name: "希瓦聚礼清真寺", desc: "中亚最独特的清真寺之一：它没有门楼和穹顶，平屋顶由213根雕花木柱支撑，木柱成排矗立，宛如森林。清真寺自10世纪起见于记载，1788–1789年形成现在的样子；一些木柱保留自更早的建筑，其中几根上还能辨认出10–11世纪的花纹。光线从屋顶的两个开口射入，形成奇妙的幽暗光影。旁边耸立着一座可以攀登的宣礼塔。" },
    ko: { name: "히바 주마 모스크", desc: "중앙아시아에서 가장 독특한 모스크 중 하나로, 정문도 돔도 없으며 평평한 지붕을 숲처럼 줄지어 선 213개의 조각된 나무 기둥이 받치고 있습니다. 10세기부터 기록에 나타나며 1788~1789년에 현재 모습이 되었고, 일부 기둥은 이전 건물에서 남은 것이어서 몇몇에는 10~11세기의 문양이 보입니다. 지붕의 두 개구부로 빛이 들어와 신비로운 어스름을 만듭니다. 옆에는 오를 수 있는 미나레트가 솟아 있습니다." },
    de: { name: "Dschuma-Moschee in Chiwa", desc: "Eine der ungewöhnlichsten Moscheen Zentralasiens: Sie hat weder Portal noch Kuppeln, und ihr Flachdach ruht auf 213 geschnitzten Holzsäulen, die in Reihen wie ein Wald stehen. Die Moschee ist seit dem 10. Jahrhundert bekannt und erhielt ihre heutige Form 1788–1789; einige Säulen stammen aus früheren Bauten, und an manchen lassen sich Muster des 10.–11. Jahrhunderts erkennen. Licht fällt durch zwei Öffnungen im Dach und schafft ein bemerkenswertes Halbdunkel. Daneben erhebt sich ein Minarett, das man besteigen kann." },
    fr: { name: "Mosquée Djouma de Khiva", desc: "L'une des mosquées les plus singulières d'Asie centrale : elle n'a ni portail ni coupoles, et son toit plat repose sur 213 colonnes de bois sculpté alignées comme une forêt. Connue dès le Xe siècle, la mosquée prit sa forme actuelle en 1788–1789 ; certaines colonnes proviennent d'édifices antérieurs, et l'on distingue sur quelques-unes des motifs des Xe–XIe siècles. La lumière entre par deux ouvertures du toit et crée une pénombre remarquable. À côté s'élève un minaret où l'on peut monter." },
    ja: { name: "ヒヴァのジュマ・モスク", desc: "中央アジアで最も変わったモスクのひとつで、門もドームもなく、平らな屋根を森のように並ぶ213本の彫刻の木柱が支えています。モスクは10世紀から知られ、1788～1789年に現在の姿になりました。一部の柱は以前の建物から受け継がれたもので、いくつかには10～11世紀の文様が見てとれます。屋根の2つの開口部から光が差し込み、独特の薄明かりをつくります。隣には登ることのできるミナレットがそびえています。" },
    tr: { name: "Hive Cuma Camii", desc: "Orta Asya'nın en sıra dışı camilerinden biri: taç kapısı ve kubbesi yoktur; düz çatısı bir orman gibi sıra sıra dizilmiş 213 oyma ahşap sütuna dayanır. Cami 10. yüzyıldan beri bilinir ve bugünkü biçimini 1788–1789'da aldı; bazı sütunlar daha önceki yapılardan kalmadır ve birkaçında 10.–11. yüzyıl desenleri seçilebilir. Işık çatıdaki iki açıklıktan girer ve etkileyici bir alacakaranlık yaratır. Yanında çıkılabilen bir minare yükselir." },
    ar: { name: "المسجد الجامع في خيوة", desc: "من أغرب مساجد آسيا الوسطى: لا بوابة له ولا قباب، وسقفه المسطح يقوم على 213 عمودًا خشبيًا منحوتًا مصفوفة كالغابة. يُعرف المسجد منذ القرن العاشر، واتخذ شكله الحالي في 1788–1789؛ وبعض أعمدته باقٍ من مبانٍ أقدم، ويمكن تمييز زخارف من القرنين العاشر والحادي عشر على بعضها. يدخل الضوء من فتحتين في السقف فيخلق شبه ظلمة لافتة. وبجانبه مئذنة يمكن صعودها." },
  },
  "kh-islamkhoja": {
    zh: { name: "伊斯兰·霍贾宣礼塔与经学院", desc: "希瓦最高的宣礼塔，高约57米，饰有绿松石色和白色瓷砖条带，旁边是一座小经学院。两者都由大维齐尔伊斯兰·霍贾于1908–1910年修建，他是一位改革者，在汗国开办了医院、邮局和世俗学校。螺旋楼梯通向塔顶，从那里可以看到整个伊钦卡拉和远处的沙漠。经学院内是花剌子模实用艺术博物馆，展出地毯、木雕和铜器。" },
    ko: { name: "이슬람 호자 미나레트와 마드라사", desc: "청록색과 흰색 타일 띠를 두른 높이 약 57m의 히바에서 가장 높은 미나레트와, 그 옆의 작은 마드라사입니다. 둘 다 칸국에 병원, 우체국, 세속 학교를 연 개혁가인 대재상 이슬람 호자가 1908~1910년에 세웠습니다. 나선 계단으로 꼭대기에 오르면 이찬 칼라 전체와 그 너머 사막이 보입니다. 마드라사에는 카펫, 목조각, 구리 그릇을 전시하는 호라즘 응용미술 박물관이 있습니다." },
    de: { name: "Minarett und Medrese Islam Chodscha", desc: "Chiwas höchstes Minarett, etwa 57 Meter, mit Bändern aus türkisfarbenen und weißen Fliesen, und daneben eine kleine Medrese. Beide wurden 1908–1910 vom Großwesir Islam Chodscha erbaut, einem Reformer, der im Khanat ein Krankenhaus, eine Post und eine weltliche Schule eröffnete. Eine Wendeltreppe führt nach oben, von wo man ganz Itschan Kala und die Wüste dahinter sieht. Die Medrese beherbergt das Choresmische Museum für angewandte Kunst mit Teppichen, Holzschnitzerei und Kupfergeschirr." },
    fr: { name: "Minaret et médersa d'Islam Khodja", desc: "Le plus haut minaret de Khiva, environ 57 mètres, cerclé de bandes de carreaux turquoise et blancs, et une petite médersa à côté. Tous deux furent bâtis en 1908–1910 par le grand vizir Islam Khodja, un réformateur qui ouvrit dans le khanat un hôpital, une poste et une école laïque. Un escalier en colimaçon mène au sommet, d'où l'on voit tout Itchan Kala et le désert au-delà. La médersa abrite le musée des arts appliqués du Khorezm, avec tapis, bois sculpté et cuivres." },
    ja: { name: "イスラム・ホジャのミナレットとメドレセ", desc: "ターコイズと白のタイルの帯をめぐらせた高さ約57mのヒヴァで最も高いミナレットと、その隣の小さなメドレセです。どちらも、ハン国に病院、郵便局、世俗の学校を開いた改革者、大宰相イスラム・ホジャが1908～1910年に建てました。らせん階段で頂上に登ると、イチャン・カラ全体とその先の砂漠が見渡せます。メドレセにはじゅうたん、木彫り、銅器を展示するホラズム応用美術博物館があります。" },
    tr: { name: "İslam Hoca Minaresi ve Medresesi", desc: "Turkuaz ve beyaz çini kuşaklarla süslü, yaklaşık 57 metrelik Hive'nin en yüksek minaresi ve yanında küçük bir medrese. İkisi de hanlıkta hastane, postane ve laik bir okul açan reformcu sadrazam İslam Hoca tarafından 1908–1910'da yaptırıldı. Döner merdivenle tepeye çıkılır; oradan tüm İçan Kale ve ötesindeki çöl görülür. Medresede halılar, ahşap oymalar ve bakır eşyalarla Harezm Uygulamalı Sanatlar Müzesi bulunur." },
    ar: { name: "مئذنة ومدرسة إسلام خوجة", desc: "أعلى مآذن خيوة، نحو 57 مترًا، تطوقها أشرطة من البلاط الفيروزي والأبيض، وبجانبها مدرسة صغيرة. بناهما الوزير الأعظم إسلام خوجة بين 1908 و1910، وكان مصلحًا افتتح في الخانية مستشفى ومكتب بريد ومدرسة علمانية. يقود درج حلزوني إلى القمة، حيث تُرى إيتشان قلعة كلها والصحراء من ورائها. وتضم المدرسة متحف خوارزم للفنون التطبيقية بالسجاد والنحت الخشبي والأواني النحاسية." },
  },
  "kh-pahlavan": {
    zh: { name: "帕赫拉万·马哈茂德陵墓", desc: "希瓦最神圣的圣地：帕赫拉万·马哈茂德（1247–1326）之墓，他是诗人、哲学家、医者和从未败北的摔跤手，被尊为城市的守护圣人。现在的建筑群顶着希瓦最大的绿松石色穹顶，形成于19世纪初；内部是带花卉图案和诗人诗句铭文的精美马约利卡彩陶。后来希瓦的汗王们也葬在这里。据说庭院里的一口井有治病的水。这是正在使用的朝圣地：请穿着得体。" },
    ko: { name: "팔본 마흐무드 영묘", desc: "히바에서 가장 성스러운 곳으로, 시인이자 철학자, 치료사, 무패의 레슬러로 도시의 수호성인으로 추앙받는 팔본 마흐무드(1247~1326)의 무덤입니다. 히바에서 가장 큰 청록색 돔을 얹은 현재의 단지는 19세기 초에 형성되었으며, 내부에는 꽃무늬와 시인의 시구를 새긴 훌륭한 마졸리카가 있습니다. 훗날 히바의 칸들도 이곳에 묻혔습니다. 안뜰의 우물물에는 치유력이 있다고 전해집니다. 지금도 순례객이 찾는 곳이니 단정하게 입으세요." },
    de: { name: "Mausoleum Pahlavan Mahmud", desc: "Chiwas heiligstes Heiligtum: das Grab von Pahlavan Mahmud (1247–1326), Dichter, Philosoph, Heiler und unbesiegter Ringer, verehrt als Schutzheiliger der Stadt. Der heutige Komplex, gekrönt von der größten türkisfarbenen Kuppel Chiwas, entstand Anfang des 19. Jahrhunderts; innen gibt es prächtige Majolika mit Blumenmustern und Inschriften aus den Versen des Dichters. Später wurden hier die Khane von Chiwa begraben. Ein Brunnen im Hof soll heilkräftiges Wasser haben. Ein aktiver Pilgerort: zurückhaltend kleiden." },
    fr: { name: "Mausolée de Pakhlavan Mahmoud", desc: "Le sanctuaire le plus saint de Khiva : le tombeau de Pakhlavan Mahmoud (1247–1326), poète, philosophe, guérisseur et lutteur invaincu, vénéré comme le saint patron de la ville. L'ensemble actuel, couronné de la plus grande coupole turquoise de Khiva, prit forme au début du XIXe siècle ; à l'intérieur, une superbe majolique à motifs floraux et des inscriptions tirées des vers du poète. Les khans de Khiva y furent ensuite inhumés. Un puits de la cour aurait une eau guérisseuse. Lieu de pèlerinage actif : tenue correcte." },
    ja: { name: "パフラヴァン・マフムード廟", desc: "ヒヴァで最も神聖な聖地で、詩人、哲学者、治療者であり無敗のレスラーでもあり、町の守護聖人として崇められるパフラヴァン・マフムード（1247～1326）の墓です。ヒヴァで最も大きなターコイズのドームを頂く現在の建築群は19世紀初頭に形づくられ、内部には花模様と詩人の詩句の銘文を配した見事なマヨリカ焼があります。のちにヒヴァのハンたちもここに葬られました。中庭の井戸の水には癒しの力があるといわれます。今も巡礼者が訪れる場所なので、控えめな服装で。" },
    tr: { name: "Pehlivan Mahmud Türbesi", desc: "Hive'nin en kutsal ziyaretgâhı: şair, filozof, hekim ve yenilmez güreşçi, şehrin koruyucu velisi olarak saygı gören Pehlivan Mahmud'un (1247–1326) mezarı. Hive'nin en büyük turkuaz kubbesiyle taçlanan bugünkü külliye 19. yüzyıl başında şekillendi; içinde çiçek desenli ve şairin dizelerinden yazıtlarla muhteşem majolikalar vardır. Sonradan Hive hanları da buraya gömüldü. Avludaki kuyunun suyunun şifalı olduğu söylenir. Faal bir ziyaret yeridir: kapalı giyinin." },
    ar: { name: "ضريح بهلوان محمود", desc: "أقدس مزارات خيوة: قبر بهلوان محمود (1247–1326)، الشاعر والفيلسوف والمعالج والمصارع الذي لم يُهزم، المبجّل بوصفه الولي الحامي للمدينة. تشكّل المجمع الحالي، المتوج بأكبر قبة فيروزية في خيوة، في أوائل القرن التاسع عشر؛ وفي داخله خزف مزجج رائع بزخارف نباتية ونقوش من أشعار الشاعر. ودُفن هنا لاحقًا خانات خيوة. ويُقال إن ماء بئر في الفناء شافٍ. مزار عامر: ارتدِ ملابس محتشمة." },
  },
  "kh-tashkhauli": {
    zh: { name: "塔什·哈乌利宫", desc: "“石院”，阿拉库利汗于1830年代在伊钦卡拉东部修建的一座奢华宫殿。它有三个庭院：后宫有为汗王和他的四位妻子而建的五座高大伊万，还有接待庭院和审判庭院。伊万墙面覆盖着阿卜杜拉·金大师制作的蓝白马约利卡彩陶，木柱和彩绘天花板是花剌子模艺术的精品。宫内有关于汗廷生活的展览。" },
    ko: { name: "토시 호블리 궁전", desc: "‘돌의 뜰’이라는 뜻으로, 알라쿨리 칸이 1830년대에 이찬 칼라 동쪽에 지은 호화로운 궁전입니다. 칸과 네 아내를 위한 높은 이완 다섯 개가 있는 하렘, 접견 정원, 재판 정원의 세 안뜰이 있습니다. 이완 벽은 압둘라 진 장인의 청백색 마졸리카로 덮여 있고, 나무 기둥과 채색 천장은 호라즘 예술의 최고 작품에 속합니다. 내부에는 칸의 궁정 생활에 관한 전시가 있습니다." },
    de: { name: "Palast Tasch Chauli", desc: "Der „Steinerne Hof“, ein prachtvoller Palast, den Allakuli Khan in den 1830er-Jahren im Osten von Itschan Kala erbaute. Er hat drei Höfe: den Harem mit fünf hohen Iwanen für den Khan und seine vier Frauen, einen Empfangshof und einen Gerichtshof. Die Iwanwände sind mit blau-weißer Majolika von Meister Abdulla Dschin bedeckt, und die Holzsäulen und bemalten Decken gehören zu den schönsten Beispielen choresmischer Kunst. Innen gibt es Ausstellungen zum Leben am Khanshof." },
    fr: { name: "Palais Tach Khaouli", desc: "La « cour de pierre », un somptueux palais bâti dans les années 1830 par Allakouli Khan dans la partie est d'Itchan Kala. Il compte trois cours : le harem, avec cinq hauts iwans pour le khan et ses quatre épouses, une cour de réception et une cour de justice. Les murs des iwans sont couverts de majolique bleue et blanche du maître Abdoulla Djin, et les colonnes de bois et plafonds peints comptent parmi les plus beaux exemples de l'art du Khorezm. À l'intérieur, des expositions évoquent la vie à la cour du khan." },
    ja: { name: "タシュ・ハウリ宮殿", desc: "「石の中庭」を意味し、アッラクリ・ハンが1830年代にイチャン・カラの東部に建てた豪華な宮殿です。ハンと4人の妻のための5つの高いイーワーンがあるハレム、謁見の中庭、裁きの中庭の3つの中庭があります。イーワーンの壁は名工アブドゥッラ・ジンによる青と白のマヨリカ焼で覆われ、木の柱と彩色天井はホラズム芸術の最高傑作のひとつです。内部ではハンの宮廷生活に関する展示が見られます。" },
    tr: { name: "Taş Havli Sarayı", desc: "“Taş Avlu”; Allakulu Han'ın 1830'larda İçan Kale'nin doğusunda yaptırdığı görkemli bir saray. Üç avlusu vardır: han ve dört eşi için beş yüksek eyvanlı harem, bir kabul avlusu ve bir adalet avlusu. Eyvan duvarları usta Abdulla Cin'in mavi-beyaz majolikalarıyla kaplıdır; ahşap sütunlar ve boyalı tavanlar Harezm sanatının en güzel örnekleri arasındadır. İçeride han sarayındaki yaşama dair sergiler bulunur." },
    ar: { name: "قصر طاش حولي", desc: "«الفناء الحجري»، قصر فخم بناه الله قولي خان في ثلاثينيات القرن التاسع عشر في الجزء الشرقي من إيتشان قلعة. له ثلاثة أفنية: الحريم بخمسة إيوانات عالية للخان وزوجاته الأربع، وفناء للاستقبال، وفناء للقضاء. جدران الإيوانات مكسوة بخزف أزرق وأبيض من صنع المعلم عبد الله جن، والأعمدة الخشبية والسقوف الملونة من أروع نماذج الفن الخوارزمي. وفي الداخل معارض عن الحياة في بلاط الخان." },
  },
  "kh-allakuli": {
    zh: { name: "阿拉库利汗经学院、商队驿站和蒂姆", desc: "东门帕尔万大门旁一组1830年代的建筑群，由阿拉库利汗修建。门楼饰有华丽马约利卡彩陶的高大经学院高出城墙，旁边是商人和骆驼一起住宿的两层商队驿站，以及带穹顶的有顶市场“蒂姆”，至今仍在出售布料、帽子和纪念品。这里是老希瓦的商业中心，也是停下来喝茶的好地方。" },
    ko: { name: "알라쿨리 칸 마드라사, 대상 숙소와 팀", desc: "동문 팔본 다르보자 옆에 알라쿨리 칸이 지은 1830년대의 건축군입니다. 화려한 마졸리카 정문을 가진 높은 마드라사가 성벽 위로 솟아 있고, 옆에는 상인들이 낙타와 함께 묵던 2층 대상 숙소와, 지금도 천, 모자, 기념품을 파는 돔 지붕의 실내 시장 ‘팀’이 있습니다. 옛 히바의 상업 중심지이자 차 한잔하며 쉬어 가기 좋은 곳입니다." },
    de: { name: "Medrese, Karawanserei und Tim Allakuli Khans", desc: "Ein Ensemble der 1830er-Jahre am östlichen Tor Palvan Darvoza, erbaut von Allakuli Khan. Die hohe Medrese mit reichem Majolika-Portal überragt die Stadtmauer, daneben stehen eine zweigeschossige Karawanserei, in der Kaufleute mit ihren Kamelen übernachteten, und ein überkuppelter Markt, der Tim, in dem noch heute Stoffe, Mützen und Souvenirs verkauft werden. Das ist das Handelsherz des alten Chiwa und ein guter Ort für eine Teepause." },
    fr: { name: "Médersa, caravansérail et tim d'Allakouli Khan", desc: "Un ensemble des années 1830 près de la porte est Palvan Darvoza, bâti par Allakouli Khan. La haute médersa au riche portail de majolique domine la muraille, et à côté se trouvent un caravansérail à deux niveaux où les marchands logeaient avec leurs chameaux et un marché couvert à coupoles, le tim, où l'on vend encore tissus, chapeaux et souvenirs. C'est le cœur commerçant du vieux Khiva et un bon endroit pour une pause thé." },
    ja: { name: "アッラクリ・ハン・メドレセ、キャラバンサライとティム", desc: "東門パルヴァン・ダルヴォザのそばにある1830年代の建築群で、アッラクリ・ハンが建てました。豪華なマヨリカ焼の門を持つ高いメドレセが城壁の上にそびえ、隣には商人がラクダとともに泊まった2階建てのキャラバンサライと、今も布地、帽子、土産物が売られるドーム屋根の屋内市場「ティム」があります。古いヒヴァの商業の中心で、お茶休憩にぴったりの場所です。" },
    tr: { name: "Allakulu Han Medresesi, Kervansarayı ve Tim", desc: "Doğudaki Pehlivan Kapı'nın yanında Allakulu Han tarafından yapılan 1830'lardan bir külliye. Zengin majolikalı taç kapısıyla yüksek medrese şehir surlarının üzerinde yükselir; yanında tüccarların develeriyle konakladığı iki katlı bir kervansaray ve bugün hâlâ kumaş, şapka ve hediyelik eşya satılan kubbeli kapalı çarşı “tim” bulunur. Eski Hive'nin ticaret kalbi ve çay molası için iyi bir yer." },
    ar: { name: "مدرسة الله قولي خان والخان والتيم", desc: "مجموعة معمارية من ثلاثينيات القرن التاسع عشر عند البوابة الشرقية «بهلوان دروازه»، بناها الله قولي خان. ترتفع المدرسة العالية ببوابتها الغنية بالخزف المزجج فوق سور المدينة، وبجانبها خان للقوافل من طابقين كان التجار ينزلون فيه مع جمالهم، وسوق مسقوف مقبب هو «التيم»، لا تزال تُباع فيه الأقمشة والقبعات والتذكارات. هذا هو القلب التجاري لخيوة القديمة ومكان جيد لاستراحة شاي." },
  },
  "kh-kutlugmurad": {
    zh: { name: "库特卢格·穆拉德·伊纳克经学院", desc: "希瓦最大的经学院之一，1804–1812年为汗王的叔父库特卢格·穆拉德·伊纳克而建。这座门楼朴素简洁的两层建筑位于塔什·哈乌利宫对面。传说它的创建者葬在经学院里，这意味着绕过了禁止在城墙内安葬的规定。庭院下面保存着一座萨尔多巴——一种带穹顶的地下蓄水池，为学生和街坊供水。" },
    ko: { name: "쿠틀루그 무라드 이나크 마드라사", desc: "칸의 숙부 쿠틀루그 무라드 이나크를 위해 1804~1812년에 지은, 히바에서 가장 큰 마드라사 중 하나입니다. 소박하고 간결한 정문을 가진 2층 건물로 토시 호블리 궁전 맞은편에 있습니다. 전설에 따르면 설립자는 마드라사 안에 묻혔는데, 이는 성벽 안 매장 금지를 피해 간 것이었습니다. 안뜰 아래에는 학생들과 마을에 물을 대던 돔형 지하 저수조 사르도바가 남아 있습니다." },
    de: { name: "Medrese Kutlug Murad Inaq", desc: "Eine der größten Medresen Chiwas, 1804–1812 für Kutlug Murad Inaq, den Onkel des Khans, erbaut. Der zweigeschossige Bau mit schlichtem, strengem Portal steht gegenüber dem Palast Tasch Chauli. Der Legende nach wurde ihr Stifter in der Medrese begraben, womit man das Verbot von Bestattungen innerhalb der Stadtmauern umging. Unter dem Hof ist eine Sardoba erhalten, eine überkuppelte unterirdische Zisterne, die Studenten und Nachbarschaft mit Wasser versorgte." },
    fr: { name: "Médersa Koutloug Mourad Inaq", desc: "L'une des plus grandes médersas de Khiva, bâtie en 1804–1812 pour Koutloug Mourad Inaq, l'oncle du khan. L'édifice à deux niveaux, au portail sobre et austère, se dresse face au palais Tach Khaouli. La légende dit que son fondateur fut enterré dans la médersa, ce qui permit de contourner l'interdiction d'inhumer à l'intérieur des murailles. Sous la cour subsiste une sardoba, citerne souterraine à coupole qui alimentait en eau les étudiants et le quartier." },
    ja: { name: "クトルグ・ムラド・イナク・メドレセ", desc: "ハンの叔父クトルグ・ムラド・イナクのために1804～1812年に建てられた、ヒヴァ最大級のメドレセです。簡素で厳かな門を持つ2階建ての建物で、タシュ・ハウリ宮殿の向かいに立っています。伝説では創建者はメドレセの中に葬られ、それは城壁内での埋葬禁止を回避するためだったといいます。中庭の下には、学生と近隣に水を供給したドーム型の地下貯水槽サルドバが残っています。" },
    tr: { name: "Kutluğ Murad İnak Medresesi", desc: "Hive'nin en büyük medreselerinden biri; hanın amcası Kutluğ Murad İnak için 1804–1812'de yapıldı. Sade ve ağırbaşlı taç kapılı iki katlı yapı Taş Havli Sarayı'nın karşısındadır. Rivayete göre kurucusu medreseye gömüldü; bu, sur içine defin yasağını aşmanın bir yoluydu. Avlunun altında öğrencilere ve mahalleye su sağlayan kubbeli bir yeraltı sarnıcı, bir sardoba korunmuştur." },
    ar: { name: "مدرسة قتلغ مراد إيناق", desc: "من أكبر مدارس خيوة، بُنيت بين 1804 و1812 لقتلغ مراد إيناق، عمّ الخان. يقف المبنى ذو الطابقين ببوابته البسيطة المتقشفة قبالة قصر طاش حولي. تقول الأسطورة إن مؤسسها دُفن في المدرسة، تحايلًا على حظر الدفن داخل أسوار المدينة. وتحت الفناء سردوبة باقية، وهي صهريج مقبب تحت الأرض كان يزوّد الطلاب والحي بالماء." },
  },
  "kh-rahimkhan": {
    zh: { name: "穆罕默德·拉希姆汗经学院", desc: "库尼亚·阿尔克城堡对面一座1871年的经学院，由穆罕默德·拉希姆汗二世修建，他也是以“费鲁兹”为笔名的诗人。在他治下，希瓦成为文学和音乐的中心：诗人、历史学家和书法家在宫廷工作，汗王本人也写诗。如今经学院是关于费鲁兹时代和希瓦汗王的博物馆展览。这座有两个庭院和高大门楼的建筑，看完库尼亚·阿尔克后顺路就能参观。" },
    ko: { name: "무함마드 라힘 칸 마드라사", desc: "쿠냐 아르크 성채 맞은편에 있는 1871년의 마드라사로, 시인 페루즈로도 알려진 무함마드 라힘 칸 2세가 지었습니다. 그의 치세에 히바는 문학과 음악의 중심지가 되어 시인, 역사가, 서예가들이 궁정에서 일했고 칸 자신도 시를 썼습니다. 지금 마드라사는 페루즈 시대와 히바 칸들에 관한 박물관 전시가 되었습니다. 두 개의 안뜰과 높은 정문을 가진 건물로, 쿠냐 아르크 바로 다음에 보기 쉽습니다." },
    de: { name: "Medrese Muhammad Rahim Khan", desc: "Eine Medrese von 1871 gegenüber der Zitadelle Kunja Ark, erbaut von Muhammad Rahim Khan II., auch bekannt als Dichter Feruz. Unter ihm wurde Chiwa ein Zentrum von Literatur und Musik: Dichter, Historiker und Kalligrafen wirkten am Hof, und der Khan selbst schrieb Verse. Heute zeigt die Medrese eine Museumsausstellung über die Zeit Feruz' und die Khane von Chiwa. Der Bau mit zwei Höfen und hohem Portal lässt sich gleich nach der Kunja Ark besichtigen." },
    fr: { name: "Médersa Muhammad Rahim Khan", desc: "Une médersa de 1871 face à la citadelle de Kounia Ark, bâtie par Muhammad Rahim Khan II, connu aussi comme le poète Férouz. Sous son règne, Khiva devint un centre de littérature et de musique : poètes, historiens et calligraphes travaillaient à la cour, et le khan lui-même écrivait des vers. La médersa présente aujourd'hui une exposition muséale sur l'époque de Férouz et les khans de Khiva. L'édifice à deux cours et haut portail se visite facilement juste après le Kounia Ark." },
    ja: { name: "ムハンマド・ラヒム・ハン・メドレセ", desc: "クフナ・アルク城塞の向かいにある1871年のメドレセで、詩人フェルーズとしても知られるムハンマド・ラヒム・ハン2世が建てました。彼の治世にヒヴァは文学と音楽の中心となり、詩人、歴史家、書家が宮廷で活躍し、ハン自身も詩を書きました。現在メドレセは、フェルーズの時代とヒヴァのハンたちについての博物館展示になっています。2つの中庭と高い門を持つ建物で、クフナ・アルクのすぐあとに見学しやすいです。" },
    tr: { name: "Muhammed Rahim Han Medresesi", desc: "Köhne Erk Kalesi'nin karşısında, şair Feruz olarak da bilinen II. Muhammed Rahim Han tarafından 1871'de yaptırılan bir medrese. Onun döneminde Hive bir edebiyat ve müzik merkezi oldu: sarayda şairler, tarihçiler ve hattatlar çalıştı, han da şiir yazdı. Bugün medresede Feruz dönemine ve Hive hanlarına dair bir müze sergisi vardır. İki avlulu ve yüksek taç kapılı yapı, Köhne Erk'in hemen ardından kolayca görülür." },
    ar: { name: "مدرسة محمد رحيم خان", desc: "مدرسة من عام 1871 قبالة قلعة كونيا أرك، بناها محمد رحيم خان الثاني، المعروف أيضًا بالشاعر «فيروز». في عهده صارت خيوة مركزًا للأدب والموسيقى: عمل في البلاط شعراء ومؤرخون وخطاطون، وكان الخان نفسه يكتب الشعر. والمدرسة اليوم معرض متحفي عن عصر فيروز وخانات خيوة. يسهل زيارة المبنى ذي الفناءين والبوابة العالية مباشرة بعد كونيا أرك." },
  },
  "kh-sayidalauddin": {
    zh: { name: "赛义德·阿劳丁陵墓", desc: "希瓦现存最古老的古迹之一：14世纪苏菲谢赫赛义德·阿劳丁的陵墓，位于穆罕默德·阿明汗经学院附近。这座小建筑低于街面，因为几个世纪以来周围的地面不断抬高。它的珍宝是覆盖着蓝白图案浮雕马约利卡彩陶的墓碑，这是金帐汗国时期艺术的罕见范例。一个受人尊敬的安静地方；请穿着得体。" },
    ko: { name: "사이드 알라우딘 영묘", desc: "히바에 남아 있는 가장 오래된 유적 중 하나로, 무함마드 아민 칸 마드라사 근처에 있는 14세기 수피 셰이흐 사이드 알라우딘의 영묘입니다. 수백 년 동안 주변 지면이 높아져서 작은 건물이 거리보다 낮게 자리하고 있습니다. 보물은 청백색 무늬의 부조 마졸리카로 덮인 묘석으로, 금장 칸국 시대 예술의 드문 예입니다. 존경받는 조용한 곳이니 단정하게 입으세요." },
    de: { name: "Mausoleum Sayid Alauddin", desc: "Eines der ältesten erhaltenen Denkmäler Chiwas: das Mausoleum des Sufi-Scheichs Sayid Alauddin aus dem 14. Jahrhundert nahe der Medrese Muhammad Amin Khan. Der kleine Bau liegt unter Straßenniveau, da der Boden ringsum über die Jahrhunderte angewachsen ist. Sein Schatz ist der Grabstein mit Reliefmajolika in blau-weißen Mustern, ein seltenes Beispiel der Kunst der Goldenen-Horde-Zeit. Ein verehrter und ruhiger Ort; zurückhaltend kleiden." },
    fr: { name: "Mausolée de Saïd Alaouddin", desc: "L'un des plus anciens monuments conservés de Khiva : le mausolée du XIVe siècle du cheikh soufi Saïd Alaouddin, près de la médersa Muhammad Amin Khan. Le petit édifice se trouve sous le niveau de la rue, le sol s'étant élevé autour de lui au fil des siècles. Son trésor est la pierre tombale revêtue de majolique en relief aux motifs bleus et blancs, rare exemple de l'art de l'époque de la Horde d'or. Un lieu vénéré et calme ; tenue correcte." },
    ja: { name: "サイイド・アラウッディン廟", desc: "ヒヴァに現存する最古の建造物のひとつで、ムハンマド・アミン・ハン・メドレセの近くにある14世紀のスーフィーのシェイフ、サイイド・アラウッディンの霊廟です。何世紀もの間に周りの地面が高くなったため、小さな建物は通りより低い位置にあります。宝は青と白の文様の浮き彫りマヨリカで覆われた墓石で、ジョチ・ウルス（金帳汗国）時代の美術の貴重な例です。崇敬される静かな場所なので、控えめな服装で。" },
    tr: { name: "Seyyid Alaaddin Türbesi", desc: "Hive'nin ayakta kalan en eski anıtlarından biri: Muhammed Emin Han Medresesi yakınında Sufi şeyh Seyyid Alaaddin'in 14. yüzyıl türbesi. Yüzyıllar içinde çevresindeki zemin yükseldiği için küçük yapı sokak seviyesinin altındadır. Hazinesi, mavi-beyaz desenli kabartma majolikayla kaplı mezar taşıdır; Altın Orda dönemi sanatının nadir bir örneği. Saygın ve sakin bir yer; kapalı giyinin." },
    ar: { name: "ضريح سيد علاء الدين", desc: "من أقدم المعالم الباقية في خيوة: ضريح الشيخ الصوفي سيد علاء الدين من القرن الرابع عشر قرب مدرسة محمد أمين خان. يقع المبنى الصغير تحت مستوى الشارع، إذ ارتفعت الأرض حوله عبر القرون. وكنزه شاهد القبر المكسو بخزف بارز بزخارف زرقاء وبيضاء، وهو مثال نادر لفن عصر القبيلة الذهبية. مكان مبجّل وهادئ؛ ارتدِ ملابس محتشمة." },
  },
  "kh-akmosque": {
    zh: { name: "阿克清真寺（白清真寺）", desc: "东门帕尔万大门旁一座17世纪的小街区清真寺，因刷白的穹顶和墙壁而被称为“白色”。它由阿努沙汗创建，19世纪重建。简朴的穹顶立方体三面环绕着木柱支撑的伊万，门上有希瓦工匠的精美雕刻。旁边是阿努沙汗的老浴室。这是繁忙商业街中的一个安静角落。" },
    ko: { name: "악 모스크(하얀 모스크)", desc: "동문 팔본 다르보자 옆에 있는 17세기의 작은 마을 모스크로, 하얗게 칠한 돔과 벽 때문에 ‘하얀’ 모스크라 불립니다. 아누샤 칸이 세웠고 19세기에 다시 지어졌습니다. 소박한 돔 지붕의 정육면체 건물을 나무 기둥의 이완이 세 면에서 둘러싸고, 문에는 히바 장인의 섬세한 조각이 있습니다. 옆에는 아누샤 칸의 옛 목욕탕이 있습니다. 붐비는 상가 사이의 조용한 곳입니다." },
    de: { name: "Ak-Moschee (Weiße Moschee)", desc: "Eine kleine Viertelsmoschee aus dem 17. Jahrhundert am östlichen Tor Palvan Darvoza, „weiß“ genannt nach ihrer gekalkten Kuppel und ihren Wänden. Sie wurde von Anuscha Khan gegründet und im 19. Jahrhundert neu gebaut. Den schlichten Kuppelwürfel umgibt auf drei Seiten ein Iwan auf Holzsäulen, und die Türen tragen feine Schnitzerei Chiwaer Handwerker. Nebenan liegt das alte Badehaus Anuscha Khans. Ein ruhiger Winkel inmitten der belebten Handelsreihen." },
    fr: { name: "Mosquée Ak (mosquée blanche)", desc: "Une petite mosquée de quartier du XVIIe siècle près de la porte est Palvan Darvoza, dite « blanche » pour sa coupole et ses murs blanchis à la chaux. Fondée par Anoucha Khan, elle fut reconstruite au XIXe siècle. Le simple cube à coupole est entouré sur trois côtés d'un iwan sur colonnes de bois, et les portes portent de fines sculptures d'artisans de Khiva. Le vieux bain d'Anoucha Khan se trouve à côté. Un coin tranquille au milieu des rangées marchandes animées." },
    ja: { name: "アク・モスク（白いモスク）", desc: "東門パルヴァン・ダルヴォザのそばにある17世紀の小さな地区のモスクで、白く塗られたドームと壁から「白い」と呼ばれています。アヌシャ・ハンが創建し、19世紀に建て直されました。簡素なドームの立方体を三方から木柱のイーワーンが囲み、扉にはヒヴァの職人による繊細な彫刻があります。隣にはアヌシャ・ハンの古い浴場があります。にぎやかな商店街の中の静かな一角です。" },
    tr: { name: "Ak Cami (Beyaz Cami)", desc: "Doğudaki Pehlivan Kapı'nın yanında 17. yüzyıldan küçük bir mahalle camii; badanalı kubbesi ve duvarları nedeniyle “Beyaz” denir. Anuşa Han tarafından kuruldu ve 19. yüzyılda yeniden yapıldı. Sade kubbeli küpü üç yandan ahşap sütunlu bir eyvan çevreler; kapılarda Hiveli ustaların ince oymaları vardır. Yanında Anuşa Han'ın eski hamamı bulunur. Kalabalık çarşı sıraları arasında sakin bir köşe." },
    ar: { name: "المسجد الأبيض (آق مسجد)", desc: "مسجد حيّ صغير من القرن السابع عشر عند البوابة الشرقية «بهلوان دروازه»، يُسمّى «الأبيض» لقبته وجدرانه المطلية بالجير. أسسه أنوشا خان وأُعيد بناؤه في القرن التاسع عشر. يحيط بالمكعب المقبب البسيط من ثلاث جهات إيوان على أعمدة خشبية، وعلى الأبواب نحت دقيق لحرفيي خيوة. وبجواره حمّام أنوشا خان القديم. ركن هادئ وسط صفوف التجارة المزدحمة." },
  },
  "kh-nurullabay": {
    zh: { name: "努鲁拉拜宫", desc: "希瓦汗王的最后一座宫殿，位于伊钦卡拉以北的迪尚卡拉，由穆罕默德·拉希姆汗二世和他的儿子伊斯凡迪亚尔汗于1906–1912年修建。在这里，花剌子模传统与20世纪初的欧洲时尚相遇：雕花柱子和马约利卡彩陶与瓷砖壁炉、枝形吊灯和灰泥装饰并存，各国使节在接待大厅受到接见。宫殿坐落在花园中，各个房间展出有关汗国最后岁月的展览。" },
    ko: { name: "누룰라보이 궁전", desc: "히바 칸들의 마지막 궁전으로, 이찬 칼라 북쪽 디숀 칼라에 무함마드 라힘 칸 2세와 그의 아들 이스판디야르 칸이 1906~1912년에 지었습니다. 이곳에서 호라즘 전통과 20세기 초 유럽 유행이 만나, 조각 기둥과 마졸리카가 타일 난로, 샹들리에, 스투코와 나란히 있으며, 접견실에서는 외국 사절을 맞았습니다. 궁전은 정원 속에 있고, 방들에는 칸국 마지막 시절에 관한 전시가 있습니다." },
    de: { name: "Palast Nurullabay", desc: "Der letzte Palast der Khane von Chiwa, in Dischan Kala nördlich von Itschan Kala, 1906–1912 von Muhammad Rahim Khan II. und seinem Sohn Isfandiyar Khan erbaut. Hier trifft choresmische Tradition auf europäische Mode des frühen 20. Jahrhunderts: Geschnitzte Säulen und Majolika stehen neben Kachelöfen, Kronleuchtern und Stuck, und im Empfangssaal wurden Gesandte empfangen. Der Palast liegt in einem Garten, und seine Räume zeigen Ausstellungen über die letzten Jahre des Khanats." },
    fr: { name: "Palais Nouroullabaï", desc: "Le dernier palais des khans de Khiva, à Dichan Kala au nord d'Itchan Kala, bâti en 1906–1912 par Muhammad Rahim Khan II et son fils Isfandiyar Khan. La tradition du Khorezm y rencontre la mode européenne du début du XXe siècle : colonnes sculptées et majolique côtoient poêles en faïence, lustres et stucs, et les ambassadeurs étaient reçus dans la salle de réception. Le palais est entouré d'un jardin, et ses salles présentent des expositions sur les dernières années du khanat." },
    ja: { name: "ヌルッラバイ宮殿", desc: "ヒヴァのハンたちの最後の宮殿で、イチャン・カラの北のディシャン・カラにあり、ムハンマド・ラヒム・ハン2世と息子イスファンディヤル・ハンが1906～1912年に建てました。ここではホラズムの伝統と20世紀初頭のヨーロッパの流行が出会い、彫刻の柱やマヨリカ焼がタイル張りのストーブ、シャンデリア、スタッコと並び、謁見の間では各国の使節が迎えられました。宮殿は庭園の中にあり、部屋ではハン国最後の時代に関する展示が見られます。" },
    tr: { name: "Nurullabay Sarayı", desc: "Hive hanlarının son sarayı; İçan Kale'nin kuzeyindeki Dişan Kale'de, II. Muhammed Rahim Han ve oğlu İsfendiyar Han tarafından 1906–1912'de yapıldı. Burada Harezm geleneği 20. yüzyıl başı Avrupa modasıyla buluşur: oyma sütunlar ve majolikalar çinili sobalar, avizeler ve alçı süslemelerle yan yanadır; kabul salonunda elçiler ağırlanırdı. Saray bir bahçe içindedir ve odalarında hanlığın son yıllarına dair sergiler bulunur." },
    ar: { name: "قصر نور الله باي", desc: "آخر قصور خانات خيوة، في ديشان قلعة شمال إيتشان قلعة، بناه محمد رحيم خان الثاني وابنه إسفنديار خان بين 1906 و1912. هنا يلتقي التقليد الخوارزمي بالموضة الأوروبية في أوائل القرن العشرين: الأعمدة المنحوتة والخزف المزجج إلى جانب المدافئ المكسوة بالبلاط والثريات والجص، وكان السفراء يُستقبلون في قاعة الاستقبال. يقع القصر في حديقة، وتعرض غرفه معارض عن السنوات الأخيرة للخانية." },
  },
  "kh-dishankala": {
    zh: { name: "希瓦外城迪尚卡拉", desc: "环绕伊钦卡拉的希瓦外城：1842年，阿拉库利汗为防御袭击，用一道约六公里长、有十座城门的土坯城墙把它围了起来。如今这里是一个充满生活气息的居民区，带伊万的庭院、古老的清真寺和经学院以及努鲁拉拜宫都隐藏在不开窗的墙后。漫步迪尚卡拉，可以看到没有游客的希瓦——它的巴扎、作坊和日常生活。北门附近可以看到残存的城墙段落。" },
    ko: { name: "히바 외성 디숀 칼라", desc: "이찬 칼라를 둘러싼 히바의 외성으로, 1842년 알라쿨리 칸이 약탈을 막기 위해 열 개의 성문이 있는 약 6km 길이의 흙벽돌 성벽으로 둘러쌌습니다. 지금은 사람들이 사는 주거 지역으로, 이완이 있는 안뜰, 오래된 모스크와 마드라사, 누룰라보이 궁전이 창 없는 벽 뒤에 숨어 있습니다. 디숀 칼라를 걸으면 시장, 공방, 일상생활이 있는 관광객 없는 히바를 볼 수 있습니다. 북문 근처에서 남아 있는 성벽 구간을 볼 수 있습니다." },
    de: { name: "Dischan Kala, Chiwas Außenstadt", desc: "Chiwas Außenstadt rund um Itschan Kala: 1842 umgab Allakuli Khan sie zum Schutz vor Überfällen mit einer etwa sechs Kilometer langen Lehmziegelmauer mit zehn Toren. Heute ist sie ein lebendiges Wohnviertel, in dem sich Höfe mit Iwanen, alte Moscheen und Medresen sowie der Nurullabay-Palast hinter fensterlosen Mauern verbergen. Ein Spaziergang durch Dischan Kala zeigt Chiwa ohne Touristen, mit Basar, Werkstätten und Alltag. Erhaltene Mauerabschnitte sieht man nahe den Nordtoren." },
    fr: { name: "Dichan Kala, la ville extérieure de Khiva", desc: "La ville extérieure de Khiva, autour d'Itchan Kala : en 1842, Allakouli Khan l'entoura d'une muraille de brique crue d'environ six kilomètres, percée de dix portes, pour la protéger des razzias. C'est aujourd'hui un quartier résidentiel bien vivant où cours à iwans, vieilles mosquées et médersas, ainsi que le palais Nouroullabaï, se cachent derrière des murs aveugles. Une promenade dans Dichan Kala montre Khiva sans touristes, avec son bazar, ses ateliers et sa vie quotidienne. Des tronçons conservés de la muraille se voient près des portes nord." },
    ja: { name: "ヒヴァの外城ディシャン・カラ", desc: "イチャン・カラを取り囲むヒヴァの外城で、1842年にアッラクリ・ハンが襲撃から守るため、10の門を持つ長さ約6kmの日干しレンガの城壁で囲みました。今は人々が暮らす住宅地で、イーワーンのある中庭、古いモスクやメドレセ、ヌルッラバイ宮殿が窓のない壁の向こうに隠れています。ディシャン・カラを歩くと、バザールや工房、日常生活のある観光客のいないヒヴァが見られます。北門の近くでは城壁の残る部分が見られます。" },
    tr: { name: "Dişan Kale, Hive'nin Dış Şehri", desc: "İçan Kale'yi çevreleyen Hive'nin dış şehri: 1842'de Allakulu Han onu akınlardan korumak için on kapılı, yaklaşık altı kilometrelik bir kerpiç surla çevirdi. Bugün eyvanlı avluların, eski cami ve medreselerin ve Nurullabay Sarayı'nın penceresiz duvarların ardına gizlendiği canlı bir yerleşim bölgesidir. Dişan Kale'de bir yürüyüş, pazarı, atölyeleri ve gündelik hayatıyla turistsiz Hive'yi gösterir. Surun ayakta kalan bölümleri kuzey kapıları yakınında görülebilir." },
    ar: { name: "ديشان قلعة، المدينة الخارجية لخيوة", desc: "المدينة الخارجية لخيوة المحيطة بإيتشان قلعة: في عام 1842 أحاطها الله قولي خان بسور من الطوب اللبن طوله نحو ستة كيلومترات وله عشر بوابات لحمايتها من الغارات. وهي اليوم حي سكني نابض بالحياة، تختبئ فيه خلف الجدران الصماء أفنية بإيوانات ومساجد ومدارس قديمة وقصر نور الله باي. وتُريك جولة في ديشان قلعة خيوة بلا سياح، ببازارها وورشها وحياتها اليومية. وتُرى أجزاء باقية من السور قرب البوابات الشمالية." },
  },
  "kh-avesta": {
    zh: { name: "乌尔根奇阿维斯塔纪念地", desc: "乌尔根奇市中心沙瓦特渠岸边的纪念建筑群，献给琐罗亚斯德教的圣书《阿维斯塔》。许多学者把它的起源与古代花剌子模联系在一起；2001年乌兹别克斯坦纪念《阿维斯塔》2700周年，纪念地正是那时建成的。一座带有火焰象征的高大石碑周围是公园、台阶和喷泉，运河堤岸是市民傍晚最喜爱的散步去处之一。" },
    ko: { name: "우르겐치 아베스타 기념지", desc: "우르겐치 중심가 샤보트 운하 강변에 있는, 조로아스터교 경전 『아베스타』에 바쳐진 기념 단지입니다. 많은 학자들이 그 기원을 고대 호라즘과 연결하며, 2001년 우즈베키스탄이 『아베스타』 2,700주년을 기념할 때 이 기념지가 세워졌습니다. 불의 상징을 담은 높은 석비를 공원, 계단, 분수가 둘러싸고 있으며, 운하 제방은 시민들이 즐겨 찾는 저녁 산책로입니다." },
    de: { name: "Avesta-Gedenkstätte in Urgentsch", desc: "Ein Gedenkkomplex im Zentrum von Urgentsch am Ufer des Schavat-Kanals, gewidmet dem Avesta, dem heiligen Buch des Zoroastrismus. Viele Forscher verbinden seine Ursprünge mit dem alten Choresmien, und 2001 beging Usbekistan das 2.700-jährige Jubiläum des Avesta, als die Gedenkstätte errichtet wurde. Eine hohe Stele mit Feuersymbolik ist von einem Park, Treppen und Springbrunnen umgeben, und die Kanaluferpromenade ist einer der liebsten Abendspaziergänge der Stadtbewohner." },
    fr: { name: "Mémorial de l'Avesta, Ourguentch", desc: "Un ensemble mémorial au centre d'Ourguentch, au bord du canal Chavat, consacré à l'Avesta, le livre sacré du zoroastrisme. De nombreux chercheurs relient ses origines à l'ancien Khorezm, et en 2001 l'Ouzbékistan célébra les 2 700 ans de l'Avesta, année de construction du mémorial. Une haute stèle à la symbolique du feu est entourée d'un parc, d'escaliers et de fontaines, et le quai du canal est l'une des promenades du soir préférées des habitants." },
    ja: { name: "ウルゲンチのアヴェスター記念碑", desc: "ウルゲンチ中心部、シャヴァト運河の岸辺にある記念建築群で、ゾロアスター教の聖典『アヴェスター』にささげられています。多くの研究者がその起源を古代ホラズムと結びつけており、2001年にウズベキスタンが『アヴェスター』2700年を記念した際にこの記念碑が建てられました。火の象徴を持つ高い石碑を公園、階段、噴水が囲み、運河の堤防は市民お気に入りの夕方の散歩道です。" },
    tr: { name: "Urgenç Avesta Anıtı", desc: "Urgenç merkezinde Şavat kanalı kıyısında, Zerdüştlüğün kutsal kitabı Avesta'ya adanmış bir anıt külliye. Pek çok bilim insanı onun kökenlerini eski Harezm'e bağlar; 2001'de Özbekistan Avesta'nın 2.700. yılını kutladığında anıt inşa edildi. Ateş simgeciliği taşıyan yüksek bir dikilitaşın çevresinde park, merdivenler ve fıskiyeler vardır; kanal kıyısı şehir halkının en sevdiği akşam yürüyüşlerinden biridir." },
    ar: { name: "نصب الأفستا في أورغنج", desc: "مجمع تذكاري في وسط أورغنج على ضفة قناة شاوات، مكرّس للأفستا، الكتاب المقدس للزرادشتية. يربط كثير من الباحثين أصوله بخوارزم القديمة، وفي عام 2001 احتفلت أوزبكستان بمرور 2700 عام على الأفستا، وفيه بُني النصب. تحيط بمسلة عالية ذات رمزية نارية حديقة وأدراج ونوافير، وكورنيش القناة من أحب نزهات المساء لدى سكان المدينة." },
  },
  "kh-manguberdi": {
    zh: { name: "扎兰丁·曼古别尔季纪念碑", desc: "献给最后一位花剌子模沙扎兰丁·曼古别尔季（1199–1231）的纪念碑。他是一位与成吉思汗大军作战十余年的统帅，成为坚韧和民族自豪的象征。雕像立在乌尔根奇市中心，四周是公园。他的一生充满传奇：据说1221年在印度河战败后，他骑马从高高的河岸跃入河中逃脱，连成吉思汗本人都为之赞叹。" },
    ko: { name: "잘랄루딘 망구베르디 기념비", desc: "마지막 호라즘샤 잘랄루딘 망구베르디(1199~1231)의 기념비로, 그는 10년 넘게 칭기즈 칸의 군대와 싸운 지휘관이자 불굴과 민족적 자부심의 상징이 되었습니다. 동상은 공원에 둘러싸여 우르겐치 중심가에 서 있습니다. 그의 삶은 전설적인데, 1221년 인더스강에서 패한 뒤 말을 탄 채 높은 강둑에서 강으로 뛰어들어 탈출해 칭기즈 칸 자신의 감탄을 샀다고 전해집니다." },
    de: { name: "Denkmal Dschalaluddin Manguberdi", desc: "Ein Denkmal für den letzten Choresmschah Dschalaluddin Manguberdi (1199–1231), einen Feldherrn, der mehr als ein Jahrzehnt gegen die Heere Dschingis Khans kämpfte und zum Symbol von Standhaftigkeit und Nationalstolz wurde. Die Statue steht im Zentrum von Urgentsch, umgeben von einem Park. Sein Leben ist legendär: Nach der Niederlage am Indus 1221 soll er zu Pferd vom hohen Ufer in den Fluss gesprungen und entkommen sein, was ihm die Bewunderung Dschingis Khans selbst einbrachte." },
    fr: { name: "Monument à Djalaluddin Mangouberdi", desc: "Un monument au dernier Khorezmchah, Djalaluddin Mangouberdi (1199–1231), un chef de guerre qui combattit les armées de Gengis Khan pendant plus d'une décennie et devint un symbole de résistance et de fierté nationale. La statue se dresse au centre d'Ourguentch, entourée d'un parc. Sa vie est légendaire : après la défaite sur l'Indus en 1221, il aurait sauté à cheval de la haute berge dans le fleuve et se serait échappé, s'attirant l'admiration de Gengis Khan lui-même." },
    ja: { name: "ジャラールッディーン・マングベルディ像", desc: "最後のホラズム・シャー、ジャラールッディーン・マングベルディ（1199～1231）の記念碑です。彼は10年以上にわたってチンギス・ハンの軍勢と戦った指揮官で、不屈と民族の誇りの象徴となりました。像はウルゲンチ中心部の公園に囲まれて立っています。彼の生涯は伝説に満ちており、1221年のインダス河畔での敗北後、馬に乗ったまま高い岸から川へ飛び込んで逃れ、チンギス・ハン自身を感嘆させたと伝えられています。" },
    tr: { name: "Celaleddin Mengüberti Anıtı", desc: "Son Harezmşah Celaleddin Mengüberti'ye (1199–1231) adanmış bir anıt; on yıldan uzun süre Cengiz Han'ın ordularıyla savaşan, direncin ve ulusal gururun simgesi olan bir komutan. Heykel Urgenç merkezinde bir parkla çevrili olarak durur. Hayatı efsanevidir: 1221'de İndus'taki yenilgiden sonra at sırtında yüksek kıyıdan nehre atlayıp kaçtığı ve Cengiz Han'ın bile hayranlığını kazandığı anlatılır." },
    ar: { name: "نصب جلال الدين منكبرتي", desc: "نصب لآخر الخوارزمشاهات جلال الدين منكبرتي (1199–1231)، القائد الذي قاتل جيوش جنكيز خان أكثر من عقد وصار رمزًا للصمود والفخر الوطني. يقف التمثال في وسط أورغنج تحيط به حديقة. حياته أسطورية: يُروى أنه بعد الهزيمة على نهر السند عام 1221 قفز بفرسه من الضفة العالية إلى النهر ونجا، فنال إعجاب جنكيز خان نفسه." },
  },
  "kh-khwarizmi": {
    zh: { name: "乌尔根奇花剌子密纪念地", desc: "乌尔根奇纪念花剌子模伟大数学家和天文学家穆罕默德·伊本·穆萨·花剌子密（约780–850）的纪念建筑群。“算法”一词来自他名字的拉丁形式，“代数”一词来自他论著的标题。他在巴格达智慧宫工作，编制了天文表并撰写了地理著作。纪念碑四周是林荫道和花坛——是拍照和短途散步的好地方。" },
    ko: { name: "우르겐치 알흐와리즈미 기념지", desc: "호라즘 출신의 위대한 수학자이자 천문학자 무함마드 이븐 무사 알흐와리즈미(약 780~850)를 기리는 우르겐치의 기념 단지입니다. ‘알고리즘’이라는 말은 그의 이름의 라틴어 형태에서, ‘대수학(algebra)’은 그의 논문 제목에서 유래했습니다. 그는 바그다드의 지혜의 집에서 일하며 천문표와 지리학 저서를 남겼습니다. 기념비 주변에는 가로수길과 화단이 있어 사진 찍고 잠시 산책하기 좋습니다." },
    de: { name: "Al-Chwarizmi-Gedenkstätte in Urgentsch", desc: "Ein Gedenkkomplex in Urgentsch zu Ehren von Muhammad ibn Musa al-Chwarizmi (um 780–850), dem großen Mathematiker und Astronomen aus Choresmien. Das Wort „Algorithmus“ stammt von der lateinischen Form seines Namens, „Algebra“ vom Titel seiner Abhandlung. Er wirkte am Haus der Weisheit in Bagdad und verfasste astronomische Tafeln und geografische Werke. Das Denkmal ist von Alleen und Blumenbeeten umgeben – ein guter Ort für Fotos und einen kurzen Spaziergang." },
    fr: { name: "Mémorial d'al-Khwarizmi, Ourguentch", desc: "Un ensemble mémorial à Ourguentch en l'honneur de Muhammad ibn Moussa al-Khwarizmi (vers 780–850), le grand mathématicien et astronome du Khorezm. Le mot « algorithme » vient de la forme latine de son nom, et « algèbre » du titre de son traité. Il travailla à la Maison de la sagesse de Bagdad et composa des tables astronomiques et des ouvrages de géographie. Le monument est entouré d'allées et de parterres – un bon endroit pour des photos et une courte promenade." },
    ja: { name: "ウルゲンチのフワーリズミー記念碑", desc: "ホラズム出身の偉大な数学者・天文学者ムハンマド・イブン・ムーサー・アル＝フワーリズミー（780頃～850）をたたえるウルゲンチの記念建築群です。「アルゴリズム」という言葉は彼の名のラテン語形に、「代数（アルジェブラ）」は彼の論文の題名に由来します。彼はバグダードの知恵の館で働き、天文表や地理学の著作を残しました。記念碑の周りには並木道と花壇があり、写真撮影や軽い散歩に最適です。" },
    tr: { name: "Urgenç Harezmi Anıtı", desc: "Harezmli büyük matematikçi ve astronom Muhammed bin Musa el-Harezmi'yi (y. 780–850) onurlandıran Urgenç'teki anıt külliye. “Algoritma” kelimesi adının Latince biçiminden, “cebir” (algebra) ise eserinin başlığından gelir. Bağdat'taki Beytü'l-Hikme'de çalıştı, astronomi tabloları ve coğrafya eserleri derledi. Anıt yollar ve çiçek tarhlarıyla çevrilidir – fotoğraf ve kısa bir yürüyüş için iyi bir yer." },
    ar: { name: "نصب الخوارزمي في أورغنج", desc: "مجمع تذكاري في أورغنج تكريمًا لمحمد بن موسى الخوارزمي (نحو 780–850)، الرياضي والفلكي العظيم من خوارزم. كلمة «خوارزمية» (algorithm) مشتقة من الصيغة اللاتينية لاسمه، و«الجبر» (algebra) من عنوان كتابه. عمل في بيت الحكمة ببغداد، ووضع جداول فلكية ومؤلفات في الجغرافيا. يحيط بالنصب جادات وأحواض زهور – مكان جيد للتصوير ونزهة قصيرة." },
  },
  "kh-ulli": {
    zh: { name: "乌利·霍夫利庄园", desc: "乌尔根奇区一座古老的花剌子模设防庄园，名字意为“大院子”。高大的带塔土坯墙后，住房环绕着一个带雕花木柱伊万的庭院——几个世纪以来，富裕的花剌子模家庭就这样生活，免受袭击和沙漠风的侵扰。修复后的庄园展示了绿洲的传统生活和建筑。是乌尔根奇和希瓦之间一个方便的停靠点。" },
    ko: { name: "울리 호블리 저택", desc: "우르겐치 지구에 있는 오래된 호라즘의 요새형 저택으로, 이름은 ‘큰 안뜰’이라는 뜻입니다. 탑이 있는 높은 흙벽돌 담 안에서 주거 공간이 조각된 나무 기둥의 이완이 있는 안뜰을 둘러싸고 있으며, 이는 호라즘의 부유한 가문들이 수백 년간 약탈과 사막 바람을 피해 살던 방식입니다. 복원된 저택은 오아시스의 전통 생활과 건축을 보여 줍니다. 우르겐치와 히바 사이에 들르기 좋은 곳입니다." },
    de: { name: "Gutshof Ulli Hovli", desc: "Ein alter befestigter Gutshof Choresmiens im Bezirk Urgentsch, dessen Name „Großer Hof“ bedeutet. Hinter hohen Lehmziegelmauern mit Türmen umgeben Wohnräume einen Hof mit Iwanen auf geschnitzten Holzsäulen – so lebten wohlhabende choresmische Familien jahrhundertelang, geschützt vor Überfällen und Wüstenwinden. Restauriert zeigt der Hof das traditionelle Leben und die Architektur der Oase. Ein praktischer Halt zwischen Urgentsch und Chiwa." },
    fr: { name: "Domaine d'Ulli Hovli", desc: "Un ancien domaine fortifié du Khorezm dans le district d'Ourguentch, dont le nom signifie « grande cour ». Derrière de hauts murs de brique crue à tours, les pièces d'habitation entourent une cour avec des iwans sur colonnes de bois sculpté – ainsi vivaient pendant des siècles les familles aisées du Khorezm, à l'abri des razzias et des vents du désert. Restauré, le domaine montre la vie traditionnelle et l'architecture de l'oasis. Une halte pratique entre Ourguentch et Khiva." },
    ja: { name: "ウリ・ホヴリ屋敷", desc: "ウルゲンチ地区にある古いホラズムの要塞化された屋敷で、名前は「大きな中庭」を意味します。塔のある高い日干しレンガの壁の内側で、居住空間が彫刻の木柱のイーワーンを持つ中庭を囲んでいます。これは、ホラズムの裕福な家族が何世紀にもわたり、襲撃や砂漠の風から身を守って暮らした姿です。修復された屋敷は、オアシスの伝統的な暮らしと建築を伝えています。ウルゲンチとヒヴァの間で立ち寄るのに便利です。" },
    tr: { name: "Ulli Havli Konağı", desc: "Urgenç ilçesinde, adı “Büyük Avlu” anlamına gelen eski bir Harezm müstahkem konağı. Kuleli yüksek kerpiç duvarların ardında yaşam alanları, oyma ahşap sütunlu eyvanları olan bir avluyu çevreler – varlıklı Harezm aileleri yüzyıllarca akınlardan ve çöl rüzgârlarından korunarak böyle yaşadı. Restore edilen konak, vahanın geleneksel yaşamını ve mimarisini gösterir. Urgenç ile Hive arasında kullanışlı bir mola yeri." },
    ar: { name: "ضيعة أولي حولي", desc: "ضيعة خوارزمية محصنة قديمة في مقاطعة أورغنج، يعني اسمها «الفناء الكبير». خلف جدران عالية من الطوب اللبن ذات أبراج، تحيط مساكن بفناء فيه إيوانات على أعمدة خشبية منحوتة – هكذا عاشت الأسر الخوارزمية الميسورة قرونًا، في مأمن من الغارات ورياح الصحراء. وتعرض الضيعة بعد ترميمها الحياة التقليدية وعمارة الواحة. محطة مناسبة بين أورغنج وخيوة." },
  },
  "kh-nationalpark": {
    zh: { name: "花剌子模国家公园", desc: "花剌子模州北部阿姆河沿岸受保护的图盖河岸林，是中亚仅存的这类森林之一。图盖林的主要树种是图兰加胡杨，柽柳和沙枣灌丛中栖息着雉鸡、野猪和许多鸟类。秋天树叶变成金黄，河岸风景格外美丽。图盖林依赖河水，因此每年春汛在这里都至关重要。请与向导同来，天热时带上水和驱虫剂。" },
    ko: { name: "호라즘 국립공원", desc: "호라즘주 북쪽 아무다리야강을 따라 보호되는 투가이 강변림으로, 중앙아시아에 마지막으로 남은 것 중 하나입니다. 투가이의 대표 나무는 투랑가 포플러이며, 위성류와 보리수나무 덤불에는 꿩, 멧돼지, 많은 새가 삽니다. 가을에는 잎이 금빛으로 물들어 강변 풍경이 특히 아름답습니다. 투가이는 강물에 의존하므로 매년 봄 홍수가 이곳에서는 중요합니다. 가이드와 함께 오고, 더울 때는 물과 벌레 퇴치제를 챙기세요." },
    de: { name: "Nationalpark Choresm", desc: "Geschützte Tugai-Auwälder entlang des Amudarja im Norden der Region Choresm, unter den letzten in Zentralasien. Der Hauptbaum des Tugai ist die Turanga-Pappel, und in Dickichten aus Tamarisken und Ölweiden leben Fasane, Wildschweine und viele Vögel. Im Herbst färbt sich das Laub golden, und die Flusslandschaft ist besonders schön. Der Tugai hängt vom Flusswasser ab, daher zählt hier jedes Frühjahrshochwasser. Mit Führer kommen, bei Hitze Wasser und Insektenschutz mitnehmen." },
    fr: { name: "Parc national du Khorezm", desc: "Des forêts riveraines de tougaï protégées le long de l'Amou-Daria, au nord de la région du Khorezm, parmi les dernières d'Asie centrale. L'arbre emblématique du tougaï est le peuplier de Touranga, et faisans, sangliers et nombreux oiseaux vivent dans les fourrés de tamaris et d'oléastres. En automne, les feuilles virent à l'or et les paysages des rives sont particulièrement beaux. Le tougaï dépend de l'eau du fleuve, si bien que chaque crue de printemps compte ici. Venez avec un guide et, par la chaleur, prévoyez de l'eau et un anti-moustiques." },
    ja: { name: "ホラズム国立公園", desc: "ホラズム州北部のアムダリヤ川沿いに保護されたトゥガイ（河畔林）で、中央アジアに残る最後のもののひとつです。トゥガイの代表的な木はトゥランガ・ポプラで、ギョリュウやヤナギバグミの茂みにはキジ、イノシシ、多くの鳥がすんでいます。秋には葉が金色に染まり、川辺の景色がことのほか美しくなります。トゥガイは川の水に頼っているため、毎年の春の増水がここでは重要です。ガイドと一緒に訪れ、暑い時期は水と虫よけを持参してください。" },
    tr: { name: "Harezm Milli Parkı", desc: "Harezm bölgesinin kuzeyinde Amuderya boyunca korunan tugay nehir kıyısı ormanları; Orta Asya'da kalan son örneklerden. Tugayın ana ağacı Turanga kavağıdır; ılgın ve iğde çalılıklarında sülünler, yaban domuzları ve pek çok kuş yaşar. Sonbaharda yapraklar altın rengine döner ve nehir kıyısı manzarası özellikle güzeldir. Tugay nehir suyuna bağlıdır, bu yüzden her bahar taşkını burada önemlidir. Rehberle gelin; sıcakta su ve böcek kovucu alın." },
    ar: { name: "منتزه خوارزم الوطني", desc: "غابات «توغاي» النهرية المحمية على امتداد نهر جيحون شمال ولاية خوارزم، من آخر ما تبقى منها في آسيا الوسطى. الشجرة الرئيسية في التوغاي هي حور «تورانغا»، وتعيش في أدغال الطرفاء والزيزفون البري طيور التدرج والخنازير البرية وطيور كثيرة. في الخريف تصفرّ الأوراق ذهبًا ويغدو منظر الضفاف جميلًا بشكل خاص. تعتمد التوغاي على ماء النهر، لذا فكل فيضان ربيعي مهم هنا. تعالَ مع مرشد، واحمل في الحر ماءً وطاردًا للحشرات." },
  },
  "kh-qalajiq": {
    zh: { name: "卡拉吉克城堡", desc: "花剌子模最古老的要塞之一，位于巴加特区卡拉库姆沙漠中，距乌尔根奇约90公里。它建于公元前4–3世纪；残留塔楼的土坯城墙矗立在一个盐湖边，日落时分，废墟和白色湖岸看起来几乎不真实。2019年该要塞被列入国家文化遗产名录，附近还开设了一处有毡房的旅游营地。穿越沙漠请找熟悉路线的司机，并带上水。" },
    ko: { name: "칼라지크 칼라 요새", desc: "우르겐치에서 약 90km 떨어진 바가트 지구 카라쿰 사막에 있는, 호라즘에서 가장 오래된 요새 중 하나입니다. 기원전 4~3세기에 세워졌으며, 탑의 흔적이 남은 흙벽돌 성벽이 소금 호수 가장자리에 서 있어 해 질 녘에는 폐허와 하얀 호숫가가 거의 비현실적으로 보입니다. 2019년 국가 문화유산 목록에 올랐고, 근처에 유르트가 있는 관광 단지가 문을 열었습니다. 길을 잘 아는 기사와 함께 사막을 건너고 물을 챙기세요." },
    de: { name: "Festung Qalajiq Qala", desc: "Eine der ältesten Festungen Choresmiens im Karakum-Sand des Bezirks Bagat, etwa 90 km von Urgentsch. Sie wurde im 4.–3. Jahrhundert v. Chr. gegründet; ihre Lehmziegelmauern mit Turmresten stehen am Rand eines Salzsees, und bei Sonnenuntergang wirken Ruinen und weiße Ufer fast unwirklich. 2019 wurde die Festung ins nationale Kulturerbe-Register aufgenommen, und in der Nähe hat ein Touristenkomplex mit Jurten eröffnet. Die Wüste mit einem ortskundigen Fahrer durchqueren und Wasser mitnehmen." },
    fr: { name: "Forteresse de Qaladjiq Qala", desc: "L'une des plus anciennes forteresses du Khorezm, dans les sables du Karakoum, district de Bagat, à environ 90 km d'Ourguentch. Fondée aux IVe–IIIe siècles av. J.-C., elle dresse ses murs de brique crue aux restes de tours au bord d'un lac salé ; au coucher du soleil, ruines et rives blanches semblent presque irréelles. En 2019, la forteresse a été inscrite au registre national du patrimoine culturel, et un complexe touristique avec des yourtes a ouvert à proximité. Traversez le désert avec un chauffeur qui connaît la route, et emportez de l'eau." },
    ja: { name: "カラジク・カラ要塞", desc: "ウルゲンチから約90km、バガト地区のカラクム砂漠にあるホラズム最古級の要塞です。紀元前4～3世紀に築かれ、塔の跡が残る日干しレンガの城壁が塩湖のほとりに立ち、夕暮れには遺跡と白い湖岸がほとんど非現実的に見えます。2019年に国の文化遺産登録簿に加えられ、近くにはユルトのある観光施設が開業しました。砂漠は道を知っているドライバーと渡り、水を持参してください。" },
    tr: { name: "Kalacık Kale", desc: "Urgenç'e yaklaşık 90 km uzaklıkta, Bağat ilçesinin Karakum kumlarında Harezm'in en eski kalelerinden biri. MÖ 4.–3. yüzyılda kuruldu; kule kalıntılı kerpiç surları bir tuz gölünün kenarında yükselir ve gün batımında kalıntılar ile beyaz kıyılar neredeyse gerçek dışı görünür. 2019'da kale ulusal kültürel miras siciline eklendi ve yakınında yurtlu bir turistik tesis açıldı. Çölü yolu bilen bir şoförle geçin ve su alın." },
    ar: { name: "قلعة قلعجيق", desc: "من أقدم قلاع خوارزم، في رمال قراقوم بمقاطعة باغات على بعد نحو 90 كم من أورغنج. أُسست في القرنين الرابع والثالث قبل الميلاد؛ وتقف أسوارها من الطوب اللبن مع بقايا أبراجها على حافة بحيرة مالحة، وعند الغروب تبدو الأطلال والشواطئ البيضاء شبه خيالية. في عام 2019 أُدرجت القلعة في السجل الوطني للتراث الثقافي، وافتُتح بالقرب منها مجمع سياحي بخيام اليورت. اعبر الصحراء مع سائق يعرف الطريق، واحمل ماءً." },
  },
};
